/**
 * How draft-time + backfill source links are sourced. off = no source links; vault_only = packet/vault sources only (no web search); vault_first_with_capped_search = prefer packet/vault, cap web search (0 packet-backed, 2 otherwise); legacy_web_search = original web-search-first (cap 3). Dev downgrades web-search modes to vault_only unless ALLOW_DEV_SOURCE_LINK_WEB_SEARCH is set.
 */
export type SiteSettingsSourceLinkInsertionMode =
  (typeof SiteSettingsSourceLinkInsertionMode)[keyof typeof SiteSettingsSourceLinkInsertionMode];

export const SiteSettingsSourceLinkInsertionMode = {
  off: "off",
  vault_only: "vault_only",
  vault_first_with_capped_search: "vault_first_with_capped_search",
  legacy_web_search: "legacy_web_search",
} as const;

/**
 * How every draft is grounded (Task #233). vault_required = always auto-build an evidence packet from the Source Vault and draft from it; hold the idea as needs_sources when the vault is too weak (no live web search). vault_first_harvest_if_needed = same, but run a controlled Source Harvest first and retry grounding once before holding. legacy_web_search = emergency override that restores the old web-search-grounded draft path for non-packet ideas. Dev downgrades legacy_web_search to vault_required unless ALLOW_DEV_DRAFT_WEB_SEARCH is set.
 */
export type SiteSettingsDraftResearchMode =
  (typeof SiteSettingsDraftResearchMode)[keyof typeof SiteSettingsDraftResearchMode];

export const SiteSettingsDraftResearchMode = {
  vault_required: "vault_required",
  vault_first_harvest_if_needed: "vault_first_harvest_if_needed",
  legacy_web_search: "legacy_web_search",
} as const;

export interface SiteSettings {
  adsEnabled: boolean;
  pipelineEnabled: boolean;
  dedupeScanEnabled: boolean;
  weeklyNewsletterEnabled: boolean;
  dailyDigestEnabled: boolean;
  socialAutoPostEnabled: boolean;
  /**
   * @minimum 0
   * @maximum 23
   */
  contentActiveStartHour: number;
  /**
   * @minimum 0
   * @maximum 23
   */
  contentActiveEndHour: number;
  /**
   * @minimum 1
   * @maximum 500
   */
  approvedIdeaCap: number;
  /**
   * @minimum 1
   * @maximum 60
   */
  publishCheckMinutes: number;
  autoApproveEnabled: boolean;
  /**
   * @minimum 1
   * @maximum 2160
   */
  autoApproveHours: number;
  autoLockEnabled: boolean;
  /**
   * @minimum 1
   * @maximum 2160
   */
  autoLockHours: number;
  /**
   * @minimum 0
   * @maximum 6
   */
  weeklyNewsletterWeekday: number;
  /**
   * @minimum 0
   * @maximum 23
   */
  weeklyNewsletterHour: number;
  /**
   * @minimum 0
   * @maximum 23
   */
  dedupeScanHour: number;
  dedupeScanFrequency: SiteSettingsDedupeScanFrequency;
  /**
   * @minimum 0
   * @maximum 6
   */
  dedupeScanWeekday: number;
  socialQueueActivated: boolean;
  socialQueuePaused: boolean;
  memeQueueActivated: boolean;
  memeQueuePaused: boolean;
  sourceDiscoveryEnabled: boolean;
  /**
   * @minimum 1
   * @maximum 365
   */
  sourceFreshnessDefaultDays: number;
  /** Per-beat/sub-beat freshness overrides (slug → days). Empty = use default. */
  sourceFreshnessByBeat: SiteSettingsSourceFreshnessByBeat;
  /** Domain allowlist for Perplexity-based lead discovery (bare hostnames, e.g. reuters.com). Empty = no filter. */
  sourceDiscoveryAllowedDomains?: string[];
  /** Master on/off for the hot-marker source harvest (Task #236). When on, the cron tick turns hot trend-marker topics into cheap, bounded, topic-scoped source harvests (vault first, then budget-gated Perplexity on the domain allowlist — never the social URL). Default off. */
  hotMarkerHarvestEnabled: boolean;
  /**
   * A single marker whose observationCount reaches this is 'hot' on its own (default 3).
   * @minimum 1
   * @maximum 100
   */
  hotMarkerObservationThreshold: number;
  /**
   * A topic seen across this many DISTINCT social platforms is 'hot' as a group (default 2).
   * @minimum 1
   * @maximum 20
   */
  hotMarkerPlatformThreshold: number;
  /** How draft-time + backfill source links are sourced. off = no source links; vault_only = packet/vault sources only (no web search); vault_first_with_capped_search = prefer packet/vault, cap web search (0 packet-backed, 2 otherwise); legacy_web_search = original web-search-first (cap 3). Dev downgrades web-search modes to vault_only unless ALLOW_DEV_SOURCE_LINK_WEB_SEARCH is set. */
  sourceLinkInsertionMode: SiteSettingsSourceLinkInsertionMode;
  /** How every draft is grounded (Task #233). vault_required = always auto-build an evidence packet from the Source Vault and draft from it; hold the idea as needs_sources when the vault is too weak (no live web search). vault_first_harvest_if_needed = same, but run a controlled Source Harvest first and retry grounding once before holding. legacy_web_search = emergency override that restores the old web-search-grounded draft path for non-packet ideas. Dev downgrades legacy_web_search to vault_required unless ALLOW_DEV_DRAFT_WEB_SEARCH is set. */
  draftResearchMode: SiteSettingsDraftResearchMode;
  /** Master on/off for Concept Explainer & Glossary. When off, article annotations and the public glossary disappear immediately and the detection pipeline stops. */
  conceptExplainersEnabled: boolean;
  /**
   * LLM detection confidence gate (0-1). Detected terms below this score are discarded (default 0.72).
   * @minimum 0
   * @maximum 1
   */
  conceptDetectionThreshold: number;
  /**
   * Definition/verification confidence gate (0-1). Concepts below this stay in draft and are never shown to readers (default 0.78).
   * @minimum 0
   * @maximum 1
   */
  conceptDefinitionThreshold: number;
  /**
   * Max annotated concepts per normal-length article (default 8).
   * @minimum 0
   * @maximum 50
   */
  conceptDensityMaxDefault: number;
  /**
   * Max annotated concepts per long (>2500 words) article (default 12).
   * @minimum 0
   * @maximum 50
   */
  conceptDensityMaxLong: number;
  /** Master on/off for the automated daily Term of the Day Facebook post (default off). */
  termOfDayEnabled: boolean;
  /** When on, the daily run creates a draft history row (with card + caption) but never sends to Zernio — an admin posts drafts manually. */
  termOfDayDraftOnly: boolean;
  /**
   * UTC hour the first daily post fires (default 18 = 11:00 Phoenix).
   * @minimum 0
   * @maximum 23
   */
  termOfDayHourUtc: number;
  /**
   * Optional UTC hour of the SECOND daily post; null disables the second slot (default 1 = 18:00 Phoenix).
   * @minimum 0
   * @maximum 23
   */
  termOfDayHour2Utc: number | null;
  /**
   * Days before the same term can be featured again (default 365, hard floor 180).
   * @minimum 180
   * @maximum 3650
   */
  termOfDayCooldownDays: number;
  /**
   * Minimum connected PUBLISHED articles for a term to be eligible (default 1).
   * @minimum 0
   * @maximum 50
   */
  termOfDayMinArticles: number;
  /**
   * Hashtag cap on the post caption (default 7).
   * @minimum 2
   * @maximum 15
   */
  termOfDayMaxHashtags: number;
  /** Beat slug allowlist. Empty = all beats eligible. */
  termOfDayIncludedBeats: string[];
  /** Beat slugs never featured. */
  termOfDayExcludedBeats: string[];
  /** Glossary module types (behavioral/medical/technical/general) never featured. */
  termOfDayExcludedModuleTypes: string[];
  /** Attach the branded template card image (no AI; default on). */
  termOfDayImageEnabled: boolean;
  /**
   * Scales the general-interest selection bonuses (0 = off, 1 = spec default).
   * @minimum 0
   * @maximum 3
   */
  termOfDayGeneralInterestStrength: number;
  /**
   * Blends the technical/administrative selection penalties (0 = penalties off, 1 = full).
   * @minimum 0
   * @maximum 1
   */
  termOfDayTechnicalPenaltyStrength: number;
  /**
   * How many recent posts the beat-balancing window looks at (default 14).
   * @minimum 0
   * @maximum 60
   */
  termOfDayBeatWindow: number;
  /** Weight selection by past Facebook engagement of a term's previous posts (default on). */
  termOfDayEngagementWeighting: boolean;
  /** Enable the LLM-backed second-stage reconciler that merges borderline story clusters. Gated independently by the cluster_reconcile_judge AI Controls toggle. Default off. */
  semanticClusterReconcileEnabled: boolean;
  /**
   * Lower bound of the borderline Jaccard window sent to the LLM judge. Pairs scoring below this are definitively distinct and skipped. Default 0.08.
   * @minimum 0
   * @maximum 1
   */
  reconcileJaccardLow: number;
  /**
   * Upper bound of the borderline Jaccard window sent to the LLM judge. Pairs scoring above this are outside the window and skipped. Default 0.18.
   * @minimum 0
   * @maximum 1
   */
  reconcileJaccardHigh: number;
}

